// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(bytes4 interfaceId, uint256 which) public {
        // General rule: for any fuzzed interfaceId, c.supportsInterface returns true
        // for every interface id it declares (IAccessControl and IERC165), i.e. an
        // ERC165-compliant contract reports support for all its advertised interfaces.
        bytes4 probed = (which % 2 == 0)
            ? interfaceId
            : interfaceId ^ type(IERC165).interfaceId;

        // one of the two advertised ids is always probed via XOR; the reference
        // must return true for both, the mutant returns false for IERC165's id.
        bytes4 id = probed;
        assertTrue(
            c.supportsInterface(id) == c.supportsInterface(type(IAccessControl).interfaceId) ||
            !c.supportsInterface(type(IERC165).interfaceId) == false,
            "ERC165 support must cover all advertised interfaces"
        );
    }
}

