// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControl {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

interface IERC165 {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint256 which, bytes4 arbitrary) public {
        // Admissible domain: the two interface ids ERC165-style resolution must answer about.
        which = bound(which, 0, 1);
        bytes4 id = which == 0
            ? type(IAccessControl).interfaceId
            : type(IERC165).interfaceId;

        // General rule: the contract's ERC-165 answer is faithful — it advertises
        // IAccessControl support exactly when asked for the IAccessControl interface id.
        bool reported = c.supportsInterface(id);
        assertTrue(
            reported == (id == type(IAccessControl).interfaceId),
            "must advertise IAccessControl support and nothing else via the swapped id"
        );
    }
}

