pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    bytes4 constant IERC165_ID = 0x01ffc9a7; // supportsInterface(bytes4)
    bytes4 IACCESS_ID;

    function setUp() public {
        c = new C(0, new address[](0), new address[](0));
        IACCESS_ID =
            bytes4(keccak256("hasRole(bytes32,address)")) ^
            bytes4(keccak256("getRoleAdmin(bytes32)")) ^
            bytes4(keccak256("grantRole(bytes32,address)")) ^
            bytes4(keccak256("revokeRole(bytes32,address)")) ^
            bytes4(keccak256("renounceRole(bytes32,address)"));
    }

    function testFuzz_property(bytes4 id) public {
        bool reported = c.supportsInterface(id);
        bool expected = (id == IACCESS_ID) || (id == IERC165_ID);
        assertTrue(reported == expected, "must advertise IAccessControl support and nothing else via the swapped id");
    }
}
